CREATE TABLE owners(id uuid PRIMARY KEY,display_name text NOT NULL CHECK(char_length(display_name) BETWEEN 1 AND 32),controller_epoch bigint NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),disabled_at timestamptz);
CREATE TABLE sessions(id uuid PRIMARY KEY,owner_id uuid NOT NULL REFERENCES owners(id),secret_hash text UNIQUE NOT NULL,expires_at timestamptz NOT NULL,revoked_at timestamptz);
CREATE TABLE bots(id uuid PRIMARY KEY,owner_id uuid NOT NULL REFERENCES owners(id),name text NOT NULL,kind text NOT NULL CHECK(kind IN ('visual','external')),controller_epoch bigint NOT NULL DEFAULT 0,archived_at timestamptz);
CREATE TABLE bot_versions(id uuid PRIMARY KEY,bot_id uuid NOT NULL REFERENCES bots(id),revision integer NOT NULL,workspace_json jsonb,program_json jsonb,program_hash text,interpreter_version integer,external_label text,UNIQUE(bot_id,revision));
CREATE TABLE bot_credentials(id uuid PRIMARY KEY,bot_id uuid NOT NULL REFERENCES bots(id),secret_hash text UNIQUE NOT NULL,scopes text[] NOT NULL,expires_at timestamptz NOT NULL,revoked_at timestamptz);
CREATE TABLE matches(id uuid PRIMARY KEY,circle_id text,host_owner_id uuid NOT NULL REFERENCES owners(id),mode text NOT NULL,phase text NOT NULL,version bigint NOT NULL,state_json jsonb NOT NULL,deadline timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX active_circle ON matches(circle_id) WHERE circle_id IS NOT NULL AND phase NOT IN ('finished','aborted','cancelled');
CREATE INDEX match_deadlines ON matches(phase,deadline);
CREATE TABLE match_seats(id text PRIMARY KEY,match_id uuid NOT NULL REFERENCES matches(id),owner_id uuid REFERENCES owners(id),bot_version_id uuid REFERENCES bot_versions(id),kind text NOT NULL,UNIQUE(match_id,id));
CREATE UNIQUE INDEX match_owner ON match_seats(match_id,owner_id) WHERE owner_id IS NOT NULL;
CREATE TABLE rounds(match_id uuid NOT NULL REFERENCES matches(id),number integer NOT NULL,state text NOT NULL,deadline timestamptz,PRIMARY KEY(match_id,number));
CREATE TABLE moves(match_id uuid NOT NULL,round_number integer NOT NULL,seat_id text NOT NULL,move text NOT NULL CHECK(move IN ('C','D')),source text NOT NULL,accepted_at timestamptz NOT NULL,PRIMARY KEY(match_id,round_number,seat_id),FOREIGN KEY(match_id,round_number) REFERENCES rounds(match_id,number),FOREIGN KEY(match_id,seat_id) REFERENCES match_seats(match_id,id));
CREATE TABLE round_results(pair_id text PRIMARY KEY,match_id uuid NOT NULL REFERENCES matches(id),round_number integer NOT NULL,result_json jsonb NOT NULL);
CREATE TABLE match_events(match_id uuid NOT NULL REFERENCES matches(id),sequence bigint NOT NULL,type text NOT NULL,visibility text NOT NULL,recipient_seat_id text,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),published_at timestamptz,PRIMARY KEY(match_id,sequence));
CREATE INDEX unpublished_events ON match_events(created_at) WHERE published_at IS NULL;
CREATE TABLE command_receipts(principal_id uuid NOT NULL,command_id uuid NOT NULL,payload_hash text NOT NULL,response jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(principal_id,command_id));
CREATE TABLE creation_keys(id uuid PRIMARY KEY,principal_id uuid NOT NULL,expires_at timestamptz NOT NULL,consumed_at timestamptz);
CREATE TABLE balance_entries(id uuid PRIMARY KEY,owner_id uuid NOT NULL REFERENCES owners(id),match_id uuid NOT NULL REFERENCES matches(id),delta integer NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(owner_id,match_id));
CREATE TABLE bot_runtime_states(match_id uuid NOT NULL REFERENCES matches(id),seat_id text NOT NULL,state_json jsonb NOT NULL DEFAULT '{}',rng_state bigint NOT NULL,last_round integer NOT NULL DEFAULT 0,PRIMARY KEY(match_id,seat_id));
CREATE TABLE owner_blocks(owner_id uuid NOT NULL REFERENCES owners(id),blocked_owner_id uuid NOT NULL REFERENCES owners(id),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(owner_id,blocked_owner_id));
CREATE TABLE reports(id uuid PRIMARY KEY,reporter_id uuid NOT NULL REFERENCES owners(id),subject_owner_id uuid NOT NULL REFERENCES owners(id),match_id uuid REFERENCES matches(id),reason text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),status text NOT NULL DEFAULT 'open');
